#!/usr/bin/env bash
set -euo pipefail

ROOT="${1:-${PROJECT_ROOT:-.}}"
APP="$ROOT/memeflow-app"
[[ -f "$APP/index.html" ]] || APP="$ROOT"

INDEX="$APP/index.html"
V26="$APP/ai-nav-layout-v26.js"
V44="$APP/bottom-nav-flush-v44.js"
V51="$APP/native-ai-sheet-v51.js"

for f in "$INDEX" "$V26" "$V44" "$V51"; do
  [[ -f "$f" ]] || {
    echo "ERROR: missing $f"
    exit 1
  }
done

DIR="$APP/.memeflow-patches/header-burger-drawer-single-owner-v3_1"
mkdir -p "$DIR"
STAMP="$(date +%Y%m%d-%H%M%S)"

INDEX_BAK="$DIR/index.html.$STAMP.bak"
V26_BAK="$DIR/ai-nav-layout-v26.js.$STAMP.bak"
V44_BAK="$DIR/bottom-nav-flush-v44.js.$STAMP.bak"
V51_BAK="$DIR/native-ai-sheet-v51.js.$STAMP.bak"

INDEX_WORK="$DIR/index.html.$STAMP.work.html"
V26_WORK="$DIR/ai-nav-layout-v26.$STAMP.work.js"
V44_WORK="$DIR/bottom-nav-flush-v44.$STAMP.work.js"
V51_WORK="$DIR/native-ai-sheet-v51.$STAMP.work.js"

OWNER="$DIR/owner.$STAMP.txt"
BURGER="$DIR/burger.$STAMP.txt"
PATCHER="$DIR/patcher.$STAMP.py"
AUDITOR="$DIR/auditor.$STAMP.py"
REPORT="$DIR/report.$STAMP.txt"

cp "$INDEX" "$INDEX_BAK"
cp "$V26" "$V26_BAK"
cp "$V44" "$V44_BAK"
cp "$V51" "$V51_BAK"

cp "$INDEX" "$INDEX_WORK"
cp "$V51" "$V51_WORK"

rollback(){
  cp "$INDEX_BAK" "$INDEX" 2>/dev/null || true
  cp "$V26_BAK" "$V26" 2>/dev/null || true
  cp "$V44_BAK" "$V44" 2>/dev/null || true
  cp "$V51_BAK" "$V51" 2>/dev/null || true
  rm -f "$INDEX_WORK" "$V26_WORK" "$V44_WORK" "$V51_WORK" "$OWNER" "$BURGER" "$PATCHER" "$AUDITOR"
}

trap 'echo; echo "ERROR: V3.1 audit/install failed. Exact pre-install files restored."; rollback' ERR

printf '%s' '' | base64 -d > "$V26_WORK"
printf '%s' '' | base64 -d > "$V44_WORK"
printf '%s' '' | base64 -d > "$OWNER"
printf '%s' '' | base64 -d > "$BURGER"
printf '%s' '' | base64 -d > "$PATCHER"
printf '%s' '' | base64 -d > "$AUDITOR"

echo "============================================================"
echo "MEMEFLOW HEADER DRAWER V3.1 — FLEXIBLE HEADER REBUILD"
echo "============================================================"

python3 "$PATCHER" "$APP" "$INDEX_WORK" "$V51_WORK" "$OWNER" "$BURGER" | tee "$REPORT"

node --check "$V26_WORK" >/dev/null
node --check "$V44_WORK" >/dev/null
node --check "$V51_WORK" >/dev/null

! grep -q '\.mobile-nav' "$V26_WORK"
! grep -q '\.mobile-nav' "$V51_WORK"
grep -q "document.querySelector('.mobile-nav')" "$V44_WORK"
! grep -q 'ensureStyle' "$V44_WORK"
! grep -q 'const css=' "$V44_WORK"
! grep -q 'setTimeout(apply' "$V44_WORK"

# Commit only after all source transforms and syntax checks pass.
cp "$INDEX_WORK" "$INDEX"
cp "$V26_WORK" "$V26"
cp "$V44_WORK" "$V44"
cp "$V51_WORK" "$V51"

echo >> "$REPORT"
python3 "$AUDITOR" "$APP" | tee -a "$REPORT"

cat > "$DIR/latest-manifest.txt" <<EOF
INDEX=$INDEX
V26=$V26
V44=$V44
V51=$V51
INDEX_BACKUP=$INDEX_BAK
V26_BACKUP=$V26_BAK
V44_BACKUP=$V44_BAK
V51_BACKUP=$V51_BAK
REPORT=$REPORT
EOF

rm -f "$INDEX_WORK" "$V26_WORK" "$V44_WORK" "$V51_WORK" "$OWNER" "$BURGER" "$PATCHER" "$AUDITOR"
trap - ERR

echo
echo "============================================================"
echo "HEADER BURGER DRAWER SINGLE OWNER V3.1: PASS"
echo "============================================================"
echo "Old inline bottom-nav CSS ............. REMOVED"
echo "mobile-icon-cleanup-v2 ................ REMOVED"
echo "V26 compact navigation ................ ZERO"
echo "V51 navigation ownership .............. ZERO"
echo "V44 navigation behavior ............... ONE"
echo "Inline navigation CSS owner ........... ONE"
echo "Burger DOM ............................ STATIC"
echo "Burger lines .......................... EXACTLY 2"
echo "Home .................................. REMOVED"
echo "Phone drawer .......................... FULL SCREEN / RIGHT"
echo "Tablet drawer ......................... RIGHT PANEL"
echo "Wallet ................................ HEADER"
echo "OpenAI ................................ FLOATING / BODY"
echo "Delayed V44 layout retry race ......... REMOVED"
echo
echo "Audit report:"
echo "  $REPORT"
echo
echo "NOW:"
echo "  Stop -> Run -> completely close old Safari tab -> reopen app"
